mapper.select:
SELECT COUNT(*) > 0
FROM project_members
WHERE project_id = #{projectId}
  AND user_id = #{userId}

SELECT role
FROM project_members
WHERE project_id = #{projectId}
  AND user_id = #{userId}

mapper.update:
UPDATE project_members
SET role = #{role}
WHERE project_id = #{projectId}
  AND user_id = #{userId}

mapper.delete:
DELETE FROM project_members
WHERE project_id = #{projectId}
  AND user_id = #{userId}
